790673019075_receipt_screenshot.png"}, {"created_at": "2026-10-08T16:17:48.638178+00:00", "destination": "GZB-1234-ab/financial/1791476225776_Sales.jpg", "id": "cf3b80ea-cb43-4db4-adde-2db461f8702d", "metadata": {"cacheControl": "no-cache", "contentLength": 1941950, "eTag": "\"4c13a602888bda1aab8fa5aebe7e2064\"", "httpStatusCode": 200, "lastModified": "2026-10-08T16:17:49.000Z", "mimetype": "image/jpeg", "size": 1941950}, "source": "GZB-1234-ab/Financial/1791476225776_Sales.jpg"}, {"created_at": "2026-10-08T16:24:46.070644+00:00", "destination": "GZB-1234-ab/financial/1791476649900_FullDay.jpg", "id": "595fa42f-e52b-4e69-9d03-a9b6349df2e2", "metadata": {"cacheControl": "no-cache", "contentLength": 373956, "eTag": "\"51a797af43ae082b85b16ac54f1d8adb\"", "httpStatusCode": 200, "lastModified": "2026-10-08T16:24:47.000Z", "mimetype": "image/jpeg", "size": 373956}, "source": "GZB-1234-ab/Financial/1791476649900_FullDay.jpg"}]$mapping$::jsonb) AS x(source text,destination text))
SELECT jsonb_build_object(
 'destination_collisions',(SELECT count(*) FROM mapping m JOIN storage.objects o ON o.bucket_id='society-documents' AND o.name=m.destination),
 'payments_affected_by_copy_trigger',(SELECT count(*) FROM public."SSP_Payment" p WHERE upper(btrim(coalesce(payment_status,''))) IN ('UNPAID','REJECTED','') AND EXISTS(SELECT 1 FROM mapping m WHERE public.payment_receipt_object_key(p.receipt_url)=m.destination OR EXISTS(SELECT 1 FROM public."SSP_Document" d WHERE d.payment=p.pay_rec_id AND public.payment_receipt_object_key(d.s3_path)=m.destination))),
 'document_references',(SELECT jsonb_agg(jsonb_build_object('document_id',d.document_id,'old_path',d.s3_path,'new_path',replace(d.s3_path,m.source,m.destination))) FROM public."SSP_Document" d JOIN mapping m ON public.payment_receipt_object_key(d.s3_path)=m.source)
) AS details;
